import fs from 'node:fs';
import path from 'node:path';

/**
 * Server-side content store for the migrated Fuhademy → Bidemy pages.
 * All page data lives in content/** (generated by scripts/extract-content.mjs).
 * Reads happen at build time (SSG) and during dev.
 */

export interface PageQuizQuestion {
  question: string;
  options: string[];
  correct: number;
  explanation: string;
}

export interface PageQuiz {
  topicId: string | null;
  subject: string | null;
  passingScore: number;
  questions: PageQuizQuestion[];
}

export interface PageTracker {
  topicId: string | null;
  topicTitle: string | null;
  subject: string | null;
  sections: string[];
  quizRequired: boolean;
}

export interface PageData {
  slug: string;
  source: string;
  area: string;
  kind: 'content' | 'topic' | 'division' | 'subject-home' | 'sim';
  title: string;
  description: string;
  subject: string | null;
  body: string;
  bodyClass?: string;
  bodyStyle?: string;
  css: string[];
  quiz: PageQuiz | null;
  tracker: PageTracker | null;
  links: string[];
  iframeSrc?: string;
}

export interface ManifestEntry {
  slug: string;
  source: string;
  area: string;
  kind: string;
  title: string;
  subject: string | null;
  file: string;
}

export interface HubChild {
  route: string;
  title: string;
  kind: string;
}

export interface HubData {
  route: string;
  dir: string;
  title: string;
  children: HubChild[];
}

const CONTENT_DIR = path.join(process.cwd(), 'content');

let manifestCache: ManifestEntry[] | null = null;
let hubsCache: HubData[] | null = null;
const pageCache = new Map<string, PageData | null>();

export function getManifest(): ManifestEntry[] {
  if (!manifestCache) {
    const raw = fs.readFileSync(path.join(CONTENT_DIR, 'manifest.json'), 'utf8');
    manifestCache = (JSON.parse(raw).pages as ManifestEntry[]) || [];
  }
  return manifestCache;
}

export function getHubs(): HubData[] {
  if (!hubsCache) {
    hubsCache = JSON.parse(fs.readFileSync(path.join(CONTENT_DIR, 'hubs.json'), 'utf8')) as HubData[];
  }
  return hubsCache;
}

export function getHub(route: string): HubData | null {
  return getHubs().find((h) => h.route === route) || null;
}

export function getStudentRoutes(): string[] {
  return getManifest()
    .filter((p) => p.area === 'students')
    .map((p) => p.slug)
    .concat(getHubs().map((h) => h.route));
}

export function getPage(route: string): PageData | null {
  const clean = route.replace(/^\/+/, '').replace(/\/+$/, '');
  if (pageCache.has(clean)) return pageCache.get(clean) || null;
  const file = path.join(CONTENT_DIR, 'pages', clean + '.json');
  let data: PageData | null = null;
  try {
    data = JSON.parse(fs.readFileSync(file, 'utf8')) as PageData;
  } catch {
    data = null;
  }
  pageCache.set(clean, data);
  return data;
}
